<script setup>
import {ref,computed} from 'vue'
import Icon from './Icon.vue'
const props=defineProps({properties:Array,profile:Object})
const emit=defineEmits(['profile','notify'])
const profile=ref({...{name:'Panorama · Corredor de demostración',logo:''},...props.profile})
const saved=ref(false)
const counts=computed(()=>Object.fromEntries(['Publicada','Borrador','Pausada','Vendida','Arrendada'].map(status=>[status,props.properties.filter(p=>p.status===status).length])))
function save(){if(!profile.value.name.trim()){emit('notify','Escribe el nombre de tu marca.');return}if(profile.value.logo&&!/^https:\/\//i.test(profile.value.logo)){emit('notify','El logo debe utilizar una URL HTTPS.');return}emit('profile',{name:profile.value.name.trim(),logo:profile.value.logo.trim()});saved.value=true}
function exportReport(){
 const safe=value=>{let text=String(value??'');if(/^[\s]*[=+@-]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"'}
 const rows=[['Código','Propiedad','Comuna','Operación','Estado','Moneda','Precio'],...props.properties.map(p=>[p.id,p.title,p.commune,p.operation,p.status,p.currency,p.price])]
 const blob=new Blob(['\uFEFF'+rows.map(row=>row.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'})
 const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Panorama-reporte-publicaciones.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)
}
</script>
<template><section class="benefits-page"><span class="eyebrow">BENEFICIOS PARA CORREDORES</span><h2>Tu marca, tus resultados y tu crecimiento.</h2><p>Herramientas incluidas en la propuesta mensual para que cada publicación trabaje a favor de tu negocio.</p><section class="panel"><h3>Tu marca y logo en cada publicación</h3><p>Personaliza la firma que acompaña tus avisos en el portal. Se guarda en este navegador de demostración.</p><form @submit.prevent="save"><div class="form-grid"><label>Nombre de la marca<input v-model="profile.name" maxlength="100" required @input="saved=false"></label><label>URL HTTPS del logo<input v-model="profile.logo" type="url" placeholder="https://..." @input="saved=false"></label></div><button class="button primary" type="submit">Guardar marca<Icon name="check"/></button><span v-if="saved" class="saved-profile" role="status">Marca actualizada en tus publicaciones.</span></form></section><section class="panel"><div class="panel-heading"><div><h3>Reporte de tus publicaciones</h3><p>Fotografía actual de tu cartera. No representa visitas, rendimiento histórico ni estadísticas trimestrales.</p></div><button class="button secondary" @click="exportReport">Descargar reporte CSV<Icon name="external"/></button></div><div class="report-states"><div v-for="(count,status) in counts" :key="status"><strong>{{count}}</strong><span>{{status}}</span></div></div></section><div class="benefits-upcoming"><section class="panel"><span class="eyebrow">BENEFICIO PREVISTO · AÚN NO DISPONIBLE</span><h3>Informes trimestrales</h3><p>Previstos con evolución de cartera, consultas, visitas y acciones comerciales. Requieren registros históricos verificables; no se generarán resultados retroactivos ficticios.</p></section><section class="panel"><span class="eyebrow">BENEFICIO PREVISTO · AÚN NO DISPONIBLE</span><h3>Capacitaciones y webinars</h3><p>Programa propuesto sobre publicaciones, fotografía inmobiliaria, atención de interesados y uso del panel. Fechas, cupos, modalidad y acceso a grabaciones se informarán cuando exista un calendario confirmado.</p></section></div></section></template>
